#!/usr/bin/env node
// Plan 25: the licences of the fonts and libraries AYAR ships are inside the app. This writes
// apps/desktop/src/renderer/app/licenses.generated.ts from the installed packages: the shipped list is the one in
// docs/dependencies.md §1 (kept here explicitly, so a package that starts shipping is a deliberate addition), each
// with its version and licence from its package.json and the text of its LICENSE file; the two fonts' OFL texts
// come from public/licenses/. A test compares the generated file with node_modules, so it cannot go stale.
//   node tools/packaging/licenses.ts            # writes the file
//   node tools/packaging/licenses.ts --check    # exits 1 when the committed file differs
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../../', import.meta.url));
const out = join(root, 'apps/desktop/src/renderer/app/licenses.generated.ts');

/** What ships (docs/dependencies.md §1), with the workspace whose node_modules resolves it. */
export interface ShippedEntry {
  name: string;
  version?: string;
  license: string;
  role?: string;
  text: string;
}

export const SHIPPED: readonly { name: string; from: string; role: string }[] = [
  { name: 'electron', from: 'apps/desktop', role: 'shell' },
  { name: 'zod', from: 'packages/protocol', role: 'protocol' },
  { name: 'intl-messageformat', from: 'packages/i18n', role: 'i18n' },
  { name: '@formatjs/icu-messageformat-parser', from: 'packages/i18n', role: 'i18n' },
  { name: '@formatjs/icu-skeleton-parser', from: 'packages/i18n', role: 'i18n' },
  { name: '@formatjs/fast-memoize', from: 'packages/i18n', role: 'i18n' },
  { name: 'svelte', from: 'apps/desktop', role: 'ui' },
  { name: 'yaml', from: 'packages/engine', role: 'engine' },
  { name: 'smol-toml', from: 'packages/engine', role: 'engine' },
  { name: 'ignore', from: 'packages/engine', role: 'engine' },
  { name: '@babel/parser', from: 'packages/analyzers', role: 'analyzers' },
  { name: 'postcss', from: 'packages/analyzers', role: 'analyzers' },
  { name: 'playwright-core', from: 'packages/probe', role: 'probe' },
  { name: 'axe-core', from: 'packages/probe', role: 'probe' },
  { name: 'pixelmatch', from: 'packages/probe', role: 'probe' },
  { name: 'pngjs', from: 'packages/probe', role: 'probe' },
  { name: 'lucide-static', from: 'apps/desktop', role: 'icons' },
];
const FONTS = [
  { name: 'Cairo', file: 'Cairo-OFL.txt', license: 'OFL-1.1' },
  { name: 'Almarai', file: 'Almarai-OFL.txt', license: 'OFL-1.1' },
];

/** The installed package as Node would resolve it from `from`: the nearest node_modules/<name> walking up. */
function packageDir(from: string, name: string): string {
  let dir = join(root, from);
  for (;;) {
    const candidate = join(dir, 'node_modules', name);
    if (existsSync(join(candidate, 'package.json'))) return candidate;
    const parent = dirname(dir);
    if (parent === dir) throw new Error(`${name} is not installed under ${from}`);
    dir = parent;
  }
}

function licenseFile(dir: string): string | null {
  const names = readdirSync(dir).filter((f) => /^licen[sc]e(\.|-|$)/i.test(f) && !/3rd|third/i.test(f));
  return names.length ? join(dir, names.sort()[0]!) : null;
}

export function collect(): { packages: ShippedEntry[]; fonts: ShippedEntry[] } {
  const packages = SHIPPED.map((p) => {
    const dir = packageDir(p.from, p.name);
    const pkg = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8')) as { version: string; license?: string | { type?: string } };
    const file = licenseFile(dir);
    if (!file) throw new Error(`no LICENSE file for ${p.name} in ${dir}`);
    return { name: p.name, version: pkg.version, license: typeof pkg.license === 'string' ? pkg.license : String(pkg.license?.type ?? ''), role: p.role, text: readFileSync(file, 'utf8').replace(/\r\n/g, '\n').trim() };
  });
  const fonts = FONTS.map((f) => ({ name: f.name, license: f.license, text: readFileSync(join(root, 'apps/desktop/src/renderer/public/licenses', f.file), 'utf8').replace(/\r\n/g, '\n').trim() }));
  return { packages, fonts };
}

export function render(data: { packages: ShippedEntry[]; fonts: ShippedEntry[] }): string {
  return [
    '// Generated by tools/packaging/licenses.ts from the installed packages (docs/dependencies.md §1). Do not edit:',
    '// run the generator; a test checks it is current.',
    'export interface ShippedLicense {',
    '  name: string;',
    '  version?: string;',
    '  license: string;',
    '  role?: string;',
    '  text: string;',
    '}',
    `export const SHIPPED_PACKAGES: readonly ShippedLicense[] = ${JSON.stringify(data.packages, null, 2)};`,
    `export const SHIPPED_FONTS: readonly ShippedLicense[] = ${JSON.stringify(data.fonts, null, 2)};`,
    '',
  ].join('\n');
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const text = render(collect());
  if (process.argv.includes('--check')) {
    const current = existsSync(out) ? readFileSync(out, 'utf8') : '';
    if (current !== text) {
      console.error(`licenses: ${out} is stale; run tools/packaging/licenses.ts`);
      process.exit(1);
    }
    console.log('licenses: current');
  } else {
    writeFileSync(out, text);
    console.log(`licenses: wrote ${out}`);
  }
}
